import React, { useState } from "react";
import { Button, FormControl, InputGroup } from "react-bootstrap";
import { FaPaperPlane } from "react-icons/fa";
import { useDispatch } from "react-redux";
import { addMessage } from "./slices/messageSlice"; // adjust path as needed
import { refreshCommunications } from "./store/thunks/refreshCommunications"; // adjust path as needed
import { useStore } from "react-redux"; // for getState()

function ControlsBar({
    selectedComm,
    fetchedProvider,
    communicationService,
    setShowThanksModal,
    onSendLocalReply,
    fhirClient,
    contextProvider,
    setCurrentPage,
    setSelectedComm,
    selectMessageById

}) {
    const [quickReply, setQuickReply] = useState("");
    const dispatch = useDispatch();
    const store = useStore();


    const handleQuickMessage = async () => {
        if (!quickReply.trim()) return;

        console.log(selectedComm);

        if (
            !selectedComm ||
            typeof selectedComm !== "object" ||
            selectedComm.resourceType !== "Communication" ||
            !selectedComm.id
        ) {
            console.info("⚠️ selectedComm is not a valid Communication resource.");

            const fallbackMessages = selectedComm?.injectedMessages;
            const lastValidMessage = Array.isArray(fallbackMessages)
                ? fallbackMessages[fallbackMessages.length - 1]
                : null;

            if (lastValidMessage?.resourceType === "Communication" && lastValidMessage.id) {
                console.info("🔁 Falling back to last injected message as reply target.");
                setSelectedComm(lastValidMessage);
            } else {
                console.warn("❌ No valid fallback Communication found.");
                return;
            }
        }

        try {
            console.log(selectedComm);
            const anchorRef = selectedComm.partOf?.[0]?.reference || `Communication/${selectedComm.id}`;
            console.log(anchorRef);
            const response = await communicationService.sendReply(selectedComm, quickReply.trim(), contextProvider);
            console.log("Quick response sent:", response);

            // ✅ Inject partOf manually for immediate threading
            const optimisticMsg = {
                ...response,
                partOf: [{ reference: anchorRef }],
                meta: {
                    isPending: true,
                    sentFromForm: true
                }
            };

            dispatch(addMessage(optimisticMsg));
            if (typeof onSendLocalReply === "function") {
                onSendLocalReply(optimisticMsg);
            }

            dispatch(refreshCommunications(anchorRef, fhirClient));
            //setCurrentPage?.(1); // safety check for optional prop

            console.log(response.id);
            console.log(selectMessageById);
            setQuickReply("");
            setShowThanksModal(false);


            // ✅ Focus inbox on sent message
            if (response?.id && typeof selectMessageById === "function") {
                console.log("Focusing on message ", response.id);
                selectMessageById(response.id);
            }



        } catch (error) {
            console.error("Error sending quick response:", error);
        }
    };

    return (
        <div className="d-flex justify-content-between align-items-center my-3">
            <InputGroup style={{ maxWidth: "400px" }}>
                <FormControl
                    placeholder="Type a quick reply and press Enter..."
                    value={quickReply}
                    onChange={(e) => setQuickReply(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === "Enter") {
                            e.preventDefault();
                            handleQuickMessage();
                        }
                    }}
                    disabled={!selectedComm || !selectedComm.id} // ⛔ Disable if no communication selected
                />
                <Button
                    variant="primary"
                    onClick={handleQuickMessage}
                    disabled={
                        !quickReply.trim() ||
                        !fetchedProvider ||
                        !selectedComm ||
                        !selectedComm.id
                    }
                >
                    <FaPaperPlane />
                </Button>
            </InputGroup>

        </div>
    );
}

export default ControlsBar;