import React, { useEffect, useState } from "react";
import FHIR from "fhirclient";
import "bootstrap/dist/css/bootstrap.min.css";
import BoxContainer from "./BoxContainer";
import CommunicationService from "./services/CommunicationService";
import { loadOrgConfig } from "./configs/loadConfig";
import { Modal, Button } from "react-bootstrap";
import { logEvent } from "./services/logService";
import { buildLoginAuditEvent } from "./services/auditEventBuilder";
import { useDispatch, useSelector } from "react-redux";
import { setOrgConfig } from "./slices/configSlice"; // ✅ Redux config slice
import { decodeJWT } from "./utils/jwtUtils";

function App() {
  console.log("App component initialized");
  const dispatch = useDispatch();
  const orgConfig = useSelector((state) => state.config.orgConfig); // ✅ Access from Redux

  const [contextPatient, setContextPatient] = useState(null);
  const [contextProvider, setContextProvider] = useState(null);
  const [encounterData, setEncounterData] = useState(null);
  const [error, setError] = useState(null);
  const [showErrorModal, setShowErrorModal] = useState(false);
  const [urlParams, setUrlParams] = useState(null);
  const [jwtData, setJwtData] = useState(null);
  const [iss, setIss] = useState(null);
  const [fhirClient, setFhirClient] = useState(null);
  const [communicationService, setCommunicationService] = useState(null);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const state = params.get("state");
    const issParam = params.get("iss");
    const launch = params.get("launch");
    const launchError = params.get("error");
    const errorDescription = params.get("error_description");

    console.log("🔗 RAW URL Params:", params.toString());
    console.log("🔍 URL Params extracted:", { state, issParam, launch, launchError, errorDescription });

    if (launchError) {
      const readable = decodeURIComponent(errorDescription || launchError);
      console.log("OAuth launch error:", readable);
      setError(`Authorization failed: ${readable}`);
      setShowErrorModal(true);
      return;
    }

    setIss(issParam);
    setUrlParams({ state, iss: issParam, launch });
    console.log("✅ SMART context set:", { state, iss: issParam, launch });

    
    //Redirect if no parameters are found
    if (!state || !issParam || !launch) {
      console.log("Missing SMART parameters, redirecting to authenticate...");
      FHIR.oauth2.authorize({
        clientId: "my_web_app",
        redirectUri: window.location.href,
        scope: "launch openid fhirUser patient/*.read encounter/*.read communication/*.read offline_access",
        state: "randomStateValue",
        iss: issParam,
        launch  // the launch context. Opaque, base64 that usually contains the patient, encounter, and provider, (smart style etc).
      });
      return;
    }

    const config = loadOrgConfig(issParam);
    console.log("🛠️ Loaded org config from issuer:", config);
    dispatch(setOrgConfig(config)); // ✅ Store config in Redux

    const fetchContextData = async () => {
      try {
        //this is called after the user has authenticated and the client is ready to use. This looks at window.location.href and extracts the parameters behind the scenes.
        const client = await FHIR.oauth2.ready();  
        setFhirClient(client);


        const tokenResponse = client?.state?.tokenResponse || {};
        const accessToken = tokenResponse.access_token;
        const refreshToken = tokenResponse.refresh_token;
        const jwtToken = tokenResponse.id_token;
        const decoded = jwtToken ? decodeJWT(jwtToken) : null;
        setJwtData(decoded);
        console.log("Decoded JWT Data:", decoded);

        const practitionerId = decoded?.fhirUser?.split("/")[1] || null;
        const encounterId = tokenResponse.encounter;

        const fetchFHIRResources = async () => {
          const practitioner = await client.request(`Practitioner/${practitionerId}`);
          const patient = await client.patient.read();
          const encounter = encounterId
            ? await client.request(`Encounter/${encounterId}`)
            : null;

          setContextProvider(practitioner);
          console.log("Context Provider:", practitioner);
          setContextPatient(patient);
          if (encounter) setEncounterData(encounter);

          // ✅ Build and log the AuditEvent
          const auditEvent = buildLoginAuditEvent({
            practitioner,
            patient
          });
          console.log("AuditEvent to log:", auditEvent);

          await logEvent(auditEvent);
        };

        try {
          await fetchFHIRResources();
        } catch (e) {
          if (e?.response?.status === 401 && refreshToken) {
            console.warn("🔄 Access token expired, attempting refresh...");
            await client.refresh();
            console.log("Refresh successful");
            await fetchFHIRResources();
          } else {
            throw e;
          }
        }
      } catch (error) {
        const rawMessage = error?.message || error.toString();
        console.error("Error Fetching FHIR Data:", rawMessage);
        setError(`FHIR Initialization Error: ${rawMessage}`);
        setShowErrorModal(true);
      }
    };

    fetchContextData();
  }, []);

  useEffect(() => {
    if (!fhirClient) return;
    setCommunicationService(new CommunicationService(fhirClient));
  }, [fhirClient]);

  return (
    <div style={{ padding: "0px 5px 5px 5px", fontFamily: "Arial, sans-serif" }}>
      {fhirClient && communicationService && orgConfig ? (
        <BoxContainer
          contextProvider={contextProvider}
          contextPatient={contextPatient}
          encounterData={encounterData}
          error={error}
          fhirClient={fhirClient}
          communicationService={communicationService}
          orgConfig={orgConfig} // ✅ still passed into BoxContainer
        />
      ) : (
        <div>Loading FHIR Client...</div>
      )}

      <Modal show={showErrorModal} onHide={() => setShowErrorModal(false)} centered>
        <Modal.Header closeButton>
          <Modal.Title>Authorization Error</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <div
            style={{
              whiteSpace: "pre-wrap",
              fontFamily: "monospace",
              fontSize: "0.95rem"
            }}
          >
            {error || "An unexpected authentication error occurred. Please try again."}
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowErrorModal(false)}>
            Dismiss
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}

export default App;