/**
 * Filters messages based on direction, priority, payload text, and status flags (starred, snoozed).
 *
 * @param {Array} messages - Array of Communication resources
 * @param {Object} options
 * @param {string} options.direction - "incoming" | "outgoing" | "both" | "starred" | "snoozed"
 * @param {Object} options.priorityFilter - e.g., { urgent: true, routine: true }
 * @param {string} options.practitionerId - Practitioner ID for flag matching
 * @param {string} [options.payloadQuery] - Optional search string to match payload content
 * @returns {Array} - Filtered message array
 */
export const filterMessages = (
  messages = [],
  { direction, priorityFilter, practitionerId, payloadQuery }) => {
  const safeQuery = typeof payloadQuery === "string" ? payloadQuery.trim() : "";

  let filtered = messages.filter((comm) => {
    const senderRef = comm.sender?.reference;
    const isOutgoing = senderRef === `Practitioner/${practitionerId}`;

    const isSnoozed = hasStatusFlag(comm, practitionerId, "snoozed");
    if (direction !== "snoozed" && isSnoozed) return false;

    const directionMatch =
      direction === "both" ||
      (direction === "incoming" && !isOutgoing) ||
      (direction === "outgoing" && isOutgoing) ||
      (direction === "starred" && hasStatusFlag(comm, practitionerId, "starred")) ||
      (direction === "snoozed" && isSnoozed);

    const priority = comm.priority?.toLowerCase();
    const priorityMatch = priorityFilter?.[priority];

    return directionMatch && priorityMatch;
  });

  // ✨ Apply payload filtering after core filters
  if (safeQuery) {
    filtered = filterMessagesByPayloadContent(filtered, safeQuery);
  }

  return filtered;
};

/**
 * Filters messages by payload content: contentString or attachment title
 *
 * @param {Array} messages - Array of Communication resources
 * @param {string} query - Case-insensitive search string
 * @returns {Array} - Filtered message array matching the payload text
 */
/**
 * Filters messages by payload content — contentString or attachment title.
 * Only applies filter when query has a non-empty, trimmed value.
 *
 * @param {Array} messages - Array of Communication resources
 * @param {string} query - Case-insensitive search string
 * @returns {Array} - Filtered message array, or original array if no query
 */
export const filterMessagesByPayloadContent = (messages = [], query = "") => {
  const safeQuery = typeof query === "string" ? query.trim().toLowerCase() : "";

  // Skip filtering if query is empty, zero-length, or not a string
  if (!safeQuery) return messages; // ✅ Only filter if there's actual input

  return messages.filter((comm) =>
    comm.payload?.some(
      (item) =>
        item.contentString?.toLowerCase().includes(safeQuery) ||
        item.contentAttachment?.title?.toLowerCase().includes(safeQuery)
    )
  );
};

// Helper to check for status flags (e.g. starred, snoozed)
const hasStatusFlag = (comm, practitionerId, code) => {
  return comm.extension?.some((ext) => {
    if (ext.url !== "http://yourdomain.org/fhir/StructureDefinition/statusFlag") return false;
    const userRef = ext.extension?.find((e) => e.url === "user")?.valueReference?.reference;
    const flagCode = ext.extension?.find((e) => e.url === "flag")?.valueCode;
    const normalizedRef = userRef?.split("/")?.pop();
    return normalizedRef === practitionerId && flagCode === code;
  });
};