// services/providerService.js

import { registerProvider } from "../slices/providerRegistrySlice";

/**
 * Fetches a provider by ID:
 * - Checks the Redux store first
 * - If not present, fetches from FHIR server and registers it
 */
export const fetchProvider = async (providerId, fhirClient, getState, dispatch) => {
    if (!providerId || !fhirClient) return null;

    // Check Redux store
    const cached = getState().providers?.[providerId];
    if (cached) return cached;

    try {
        const fetched = await fhirClient.request(`Practitioner/${providerId}`);
        dispatch(registerProvider(fetched));
        return fetched;
    } catch (err) {
        if (err?.response?.status === 410) {
            console.warn(`⚠️ Practitioner/${providerId} has been deleted (410 Gone).`);
            return null;
        }

        console.error("? Failed to fetch provider:", err);
        return null;
    }
};

export const fetchProviderByReference = async (ref, fhirClient, getState, dispatch) => {
    if (!ref || !ref.startsWith("Practitioner/") || ref === "Practitioner/undefined") {
        console.warn("⚠️ Invalid provider reference:", ref);
        return null;
    }

    const providerId = ref.split("/")[1];
    if (!providerId) {
        console.warn("⚠️ Could not extract provider ID from reference:", ref);
        return null;
    }

    return fetchProvider(providerId, fhirClient, getState, dispatch);
};

export async function getCircleOfCare(patientId, fhirClient) {
    if (!patientId) {
        throw new Error("Patient ID is required to fetch circle of care.");
    }

    try {
        // Run queries in parallel
        const [
            careTeamPractitioners,
            relatedPractitioners,
            orgPractitioners,
            communicationPractitioners
        ] = await Promise.all([
            fetchCareTeamPractitioners(patientId, fhirClient),
            fetchRelatedPersonPractitioners(patientId, fhirClient),
            fetchOrganizationsPractitioners(patientId, fhirClient),
            fetchCommunicationSenders(patientId, fhirClient)
        ]);

        // Merge and deduplicate by ID
        const all = [
            ...careTeamPractitioners,
            ...relatedPractitioners,
            ...orgPractitioners,
            ...communicationPractitioners
        ];

        const deduped = Object.values(
            all.reduce((acc, p) => {
                if (p?.id) acc[p.id] = p;
                return acc;
            }, {})
        );

        return deduped;
    } catch (err) {
        console.error("❌ Failed to get circle of care:", err);
        throw err;
    }
}

// 1. Get CareTeam Practitioners
export async function fetchCareTeamPractitioners(patientId, client, getState, dispatch) {
    console.log("Fetching care team practitioners for patient:", patientId);
    const bundle = await client.request(`CareTeam?patient=Patient/${patientId}`);
    const teams = bundle?.entry?.map(e => e.resource) || [];

    const references = teams
        .flatMap(t =>
            t.participant
                ?.map(p => p.member?.reference)
                .filter(ref => ref?.startsWith("Practitioner/")) || []
        );

    const uniqueIds = [...new Set(references.map(ref => ref.split("/")[1]))];

    const practitioners = await Promise.all(
        uniqueIds.map(id => fetchProvider(id, client, getState, dispatch))
    );

    return practitioners.filter(Boolean);
}


