// 4. Get Communication senders
export async function fetchCommunicationSenders(patientId, client, getState, dispatch) {
    console.log("Fetching communication senders for patient:", patientId);
    const bundle = await client.request(`Communication?subject=Patient/${patientId}`);
    const comms = bundle?.entry?.map((e) => e.resource) || [];

    const refs = comms
        .map((c) => c.sender?.reference)
        .filter((ref) => ref?.startsWith("Practitioner/"));

    const uniqueIds = [...new Set(refs.map((ref) => ref.split("/")[1]))];

    const practitioners = await Promise.all(
        uniqueIds.map((id) => fetchProvider(id, client, getState, dispatch))
    );

    console.log("Found practitioners from communications:", practitioners);
    return practitioners.filter(Boolean);
}


// 🔁 Utility: Deduplicated resolution of Practitioner references
export async function fetchPractitionersByRefs(refs, client) {
    const uniqueRefs = [...new Set(refs)];
    const practitioners = [];

    for (const ref of uniqueRefs) {
        try {
            const p = await client.request(ref);
            practitioners.push(p);
        } catch (err) {
            console.warn(`⚠️ Failed to fetch practitioner: ${ref}`, err);
        }
    }

    return practitioners;
}

/**
 * Search for providers (Practitioner resources) by a search term (name, family, or given).
 * Returns an array of matching Practitioner resources.
 * @param {string} searchTerm
 * @param {object} fhirClient
 * @returns {Promise<Array>}
 */
export async function searchProvidersByTerm(searchTerm, fhirClient) {
    if (!searchTerm || !fhirClient) return [];
    try {
        const bundle = await fhirClient.request(`Practitioner?name=${encodeURIComponent(searchTerm)}`);
        return bundle?.entry?.map(e => e.resource) || [];
    } catch (error) {
        console.error("Failed to search providers:", error);
        return [];
    }



} 