import React, { useState, useEffect, useRef } from "react";
import { Card, Button, Form, Row, Col, Modal, Badge } from "react-bootstrap";
import styles from "./CommunicationForm.module.css";
import PatientCard from "../cards/PatientCard";
import EncounterCard from "../cards/EncounterCard";
import ProviderSearch from "../ProviderSearch";
import { FaSearch, FaEye, FaTimes } from "react-icons/fa";
import { useDispatch, useSelector } from "react-redux";
import { addMessage } from "../slices/messageSlice"; // Adjust path if needed
import { refreshCommunications } from "../store/thunks/refreshCommunications"; // adjust path as needed
import { fetchProvider } from "../services/providerService";
import { useStore } from "react-redux";
import { buildCommunicationAuditEvent } from "../services/auditEventBuilder";
import { logEvent } from "../services/logService";
import { toBase64 } from "../utils/fileUtils";
import AttachmentBrowser from "./AttachmentBrowser"; // adjust path if needed
import { FaFilePdf, FaFileImage, FaFileAlt, FaFile } from "react-icons/fa";


function CommunicationForm({
    contextProvider,
    patientData,
    encounterData,
    inContext,
    commService,
    recipient,
    replyToCommId,
    fhirClient,
    onCloseForm,
    initialRecipients = [],
    onSendLocalReply,
    selectMessageById

}) {
    const [message, setMessage] = useState("");
    const [priority, setPriority] = useState("routine");
    const [category, setCategory] = useState("notification");
    const [about, setAbout] = useState("");
    const [reason, setReason] = useState("");
    const [attachment, setAttachment] = useState(null);
    const [error, setError] = useState("");
    const [showStatusModal, setShowStatusModal] = useState(false);
    const [submissionResult, setSubmissionResult] = useState("");
    const defaultTopic = `${(patientData.name?.[0]?.given?.join(" ") + " " + patientData.name?.[0]?.family) || "Progress Update"} - ${encounterData?.reasonCode?.[0]?.coding?.[0]?.display || encounterData?.type?.[0]?.text || "Unknown Encounter"}`;
    const [topic, setTopic] = useState(defaultTopic);
    const [selectedProvider, setSelectedProvider] = useState(replyToCommId ? recipient || null : null);
    const [selectedPatient, setSelectedPatient] = useState(patientData || null);
    const dispatch = useDispatch();
    const store = useStore();
    const [recipients, setRecipients] = useState(() =>
        replyToCommId && initialRecipients.length > 0 ? initialRecipients : []
    );
    const providers = useSelector((state) => state.providers);
    const onRecipientsChange = (updatedRecipients) => {
        setRecipients(updatedRecipients);
    };

    const removeRecipient = (id, type) => {
        const updated = recipients.filter(r => !(r.id === id && r.resourceType === type));
        setRecipients(updated);
        if (onRecipientsChange) onRecipientsChange(updated);
    };

    const updateTopicFromEncounter = (encounter) => {
        if (!encounter || !selectedPatient) return;

        const patientName = `${selectedPatient.name?.[0]?.given?.join(" ") ?? ""} ${selectedPatient.name?.[0]?.family ?? ""}`.trim();
        const reason = encounter.reasonCode?.[0]?.coding?.[0]?.display;
        const type = encounter.type?.[0]?.text;
        const newTopic = `${patientName || "Progress Update"} - ${reason || type || "Unknown Encounter"}`;

        setTopic(newTopic);
        console.log("Updated topic:", newTopic);
    };

    const [showAttachments, setShowAttachments] = useState(false);
    const [selectedDocuments, setSelectedDocuments] = useState([]);
    const handleRemoveAttachment = (index) => {
        const updatedDocs = [...selectedDocuments];
        updatedDocs.splice(index, 1);
        setSelectedDocuments(updatedDocs);
    };

    const fileInputRef = useRef(null);


    useEffect(() => {
        async function hydrateInitialRecipients() {
            if (!initialRecipients?.length || !fhirClient || !dispatch) return;

            for (const recipient of initialRecipients) {
                if (recipient.resourceType === "Practitioner") {
                    await fetchProvider(recipient.id, fhirClient, store.getState, dispatch);
                }
            }
        }

        hydrateInitialRecipients();
    }, [initialRecipients, fhirClient, dispatch]);

    const handleSubmit = async (e) => {
        console.log("Submitting communication...........:");
        e.preventDefault();
        if (!message.trim()) {
            setError("Message content cannot be empty.");
            return;
        }
        let anchorReference = null;
        if (replyToCommId && fhirClient) {
            try {
                const parentComm = await fhirClient.request(`Communication/${replyToCommId}`);
                if (!parentComm.partOf?.[0]?.reference) {
                    console.warn("❗ Reply target has no anchor. This should not happen.");
                    return;
                }
                anchorReference = parentComm.partOf[0].reference;
            } catch (err) {
                console.error("Error retrieving parent communication:", err);
                return;
            }
        }

        if (!replyToCommId && fhirClient) {
            try {
                const anchorComm = await fhirClient.create({
                    resourceType: "Communication",
                    status: "completed",
                    topic: {
                        coding: [
                            {
                                system: "http://example.com/custom-topic-system",
                                code: "thread-root",
                                display: topic || "Conversation Thread"
                            }
                        ]
                    },
                    subject: { reference: `Patient/${patientData?.id}` },
                    encounter: { reference: `Encounter/${encounterData?.id}` },
                    sent: new Date().toISOString(),
                    payload: [{ contentString: "Anchor for new conversation thread." }]
                });

                anchorReference = `Communication/${anchorComm.id}`;
            } catch (err) {
                console.error("Error creating anchor for new conversation:", err);
            }
        }

        let binaryResource = null;
        if (attachment && fhirClient) {
            try {
                const base64Data = await toBase64(attachment);
                binaryResource = await fhirClient.create({
                    resourceType: "Binary",
                    contentType: attachment.type,
                    data: base64Data
                });
            } catch (err) {
                console.error("Error uploading attachment as Binary:", err);
                setSubmissionResult("❌ Failed to upload attachment.");
                setShowStatusModal(true);
                return;
            }
        }

        console.log("selectedDocuments:", selectedDocuments);
        const communicationPayload = {
            resourceType: "Communication",
            status: "completed",
            sender: { reference: `Practitioner/${contextProvider?.id}` },
            recipient: recipients.map((r) => ({
                reference: `${r.resourceType}/${r.id}`
            })),
            subject: { reference: `Patient/${patientData?.id}` },
            encounter: { reference: `Encounter/${encounterData?.id}` },
            topic: {
                coding: [
                    {
                        system: "http://example.com/custom-topic-system",
                        code: "progress-update",
                        display: topic
                    }
                ]
            },
            priority: priority || "routine",
            category: [
                {
                    coding: [
                        {
                            system: "http://terminology.hl7.org/CodeSystem/communication-category",
                            code: category,
                            display: category.charAt(0).toUpperCase() + category.slice(1)
                        }
                    ]
                }
            ],
            about: about ? [{ reference: about }] : [],
            reasonCode: reason
                ? [{ coding: [{ system: "http://snomed.info/sct", code: reason, display: reason }] }]
                : [],
            ...(anchorReference ? { partOf: [{ reference: anchorReference }] } : {}),
            ...(replyToCommId ? { inResponseTo: [{ reference: `Communication/${replyToCommId}` }] } : {}),
            payload: [
                { contentString: message },

                // Manually uploaded file
                ...(attachment && binaryResource?.id
                    ? [{
                        contentAttachment: {
                            contentType: attachment.type,
                            url: `Binary/${binaryResource.id}`,
                            title: attachment.name
                        }
                    }]
                    : []),

                ...selectedDocuments
                    .filter(doc => doc.resource.content?.[0]?.attachment?.url)
                    .map(doc => ({
                        contentAttachment: {
                            contentType: doc.resource?.content[0].attachment.contentType,
                            url: doc.resource.content[0].attachment.url,
                            title: doc.resource.content[0].attachment.title
                        }
                    }))
            ],
            sent: new Date().toISOString(),
            extension: [
                {
                    url: "http://yourdomain.org/fhir/StructureDefinition/read-receipt",
                    extension: [
                        {
                            url: "user",
                            valueReference: {
                                reference: `Practitioner/${contextProvider?.id}`
                            }
                        },
                        {
                            url: "readAt",
                            valueDateTime: new Date().toISOString()
                        }
                    ]
                }
            ]
        };

        try {
            const response = await commService.createCommunication(communicationPayload);
            console.log("📨 Message created:", response);

            if (!response) {
                throw new Error("No response from CommunicationService.");
            }

            // 🧭 Derive anchor ID safely from known sources
            const anchorId =
                anchorReference?.split("/")[1] ||
                replyToCommId ||
                response.partOf?.[0]?.reference?.split("/")[1];

            const anchorRef = `Communication/${anchorId}`;

            // 🚀 Inject optimistic message into thread immediately. ....
            const optimisticMsg = {
                ...response,
                partOf: [{ reference: anchorRef }],
                meta: {
                    isPending: true,
                    sentFromForm: true
                }
            };

            dispatch(addMessage(optimisticMsg));

            // 🔁 Update local thread viewer if wired
            if (typeof onSendLocalReply === "function") {
                onSendLocalReply(optimisticMsg);
            }

            // 🛰️ Fetch any updated server messages in background
            dispatch(refreshCommunications(anchorRef, fhirClient));

            // ✅ UI feedback + cleanup
            setSubmissionResult("✅ Message sent successfully!");
            setMessage("");
            setAttachment(null);
            setPriority("routine");
            setCategory("notification");
            setAbout("");
            setReason("");
            setTopic(defaultTopic);
            setError("");

            if (!replyToCommId) {
                setSelectedProvider(null);
            }

            if (typeof onCloseForm === "function") {
                onCloseForm();
            }

            // ✅ Focus inbox on sent message
            if (response?.id && typeof selectMessageById === "function") {
                console.log("Focusing on message ", response.id);
                selectMessageById(response.id);
            }

            // 🎉 Show status modal
            setShowStatusModal(false);

            const auditEvent = buildCommunicationAuditEvent({ communication: response });
            await logEvent(auditEvent);

        } catch (error) {
            console.error("❌ Error sending communication:", error);
            setSubmissionResult("❌ Failed to send message. Please try again.");
        }
    };

    return (
        <Row>
            {/* West: Provider Search */}
            <Col md={4}>
                <Card className="h-100">
                    <Card.Body>
                        <h5>Provider Search</h5>
                        <ProviderSearch
                            fhirClient={fhirClient}
                            patientId={patientData?.id}
                            onSelect={setSelectedProvider}
                            recipients={recipients}
                            onRecipientsChange={onRecipientsChange}
                        />
                    </Card.Body>
                </Card>
            </Col>
            {/* East: Everything else */}
            <Col md={8}>
                Recipients:
                {recipients.length === 0 ? (
                    <div className="text-muted mb-2">No recipients selected</div>
                ) : (
                    <div
                        className="mb-2"
                        style={{
                            maxHeight: "100px",
                            overflowY: "auto",
                            padding: "0.25rem",
                            border: "1px solid #ddd",
                            borderRadius: "4px"
                        }}
                    >
                        {recipients.map((r) => {
                            const provider = r.resourceType === "Practitioner" ? providers?.[r.id] : null;

                            const name =
                                provider?.name?.[0]?.text ||
                                [provider?.name?.[0]?.given?.join(" "), provider?.name?.[0]?.family].filter(Boolean).join(" ") ||
                                r.name?.[0]?.text ||
                                [r.name?.[0]?.given?.join(" "), r.name?.[0]?.family].filter(Boolean).join(" ") ||
                                r.id;

                            return (
                                <Badge
                                    key={r.resourceType + "/" + r.id}
                                    bg="primary"
                                    className="me-1 mb-1 d-inline-flex align-items-center"
                                    style={{ fontSize: "1em", whiteSpace: "nowrap", paddingRight: "0.5rem" }}
                                >
                                    {name}
                                    <FaTimes
                                        onClick={() => removeRecipient(r.id, r.resourceType)}
                                        style={{
                                            marginLeft: "6px",
                                            cursor: "pointer",
                                            fontSize: "0.9em"
                                        }}
                                        title="Remove recipient"
                                    />
                                </Badge>
                            );
                        })}

                    </div>
                )}
                <Card className="mt-0">
                    <Card.Body>
                        <Row>
                            <Col md={6}>
                                <PatientCard
                                    title="Re: Patient"
                                    patientData={patientData}
                                    inContext={inContext}
                                    showSearch={true}
                                    fhirClient={fhirClient}
                                    onSelectPatient={(patient) => setSelectedPatient(patient)}

                                />
                            </Col>
                            <Col md={6}>
                                <EncounterCard
                                    title="Re: Encounter"
                                    encounterData={encounterData}
                                    inContext={inContext}
                                    patientId={selectedPatient?.id}
                                    fhirClient={fhirClient}
                                    enableSearch={true}
                                    onEncounterChange={(enc) => updateTopicFromEncounter(enc)}


                                />
                            </Col>
                        </Row>

                        <Form onSubmit={handleSubmit} className="mt-2">
                            <Row className="mt-0">
                                <Form.Group controlId="topicInput" className="mt-0">
                                    <Form.Label><strong>Topic</strong></Form.Label>
                                    <Form.Control
                                        type="text"
                                        value={topic}
                                        onChange={(e) => setTopic(e.target.value)}
                                        placeholder="Enter communication topic"
                                    />
                                </Form.Group>
                            </Row>

                            <Row className="mt-3">
                                <Col md={6}>
                                    <Form.Group controlId="prioritySelect">
                                        <Form.Label><strong>Priority</strong></Form.Label>
                                        <Form.Select value={priority} onChange={(e) => setPriority(e.target.value)}>
                                            <option value="routine">Routine</option>
                                            <option value="urgent">Urgent</option>
                                            <option value="asap">ASAP</option>
                                            <option value="stat">STAT</option>
                                        </Form.Select>
                                    </Form.Group>
                                </Col>
                                <Col md={6}>
                                    <Form.Group controlId="categorySelect" className="mt-0">
                                        <Form.Label><strong>Category</strong></Form.Label>
                                        <Form.Select value={category} onChange={(e) => setCategory(e.target.value)}>
                                            <option value="alert">Alert</option>
                                            <option value="notification">Notification</option>
                                            <option value="reminder">Reminder</option>
                                            <option value="instruction">Instruction</option>
                                        </Form.Select>
                                    </Form.Group>
                                </Col>
                            </Row>
                            <Form.Group controlId="messageTextArea" className="mt-3">
                                <Form.Label><strong>Message Content</strong></Form.Label>
                                <Form.Control
                                    as="textarea"
                                    rows={4}
                                    value={message}
                                    onChange={(e) => setMessage(e.target.value)}
                                    placeholder="Type your message here..."
                                />

                                {/* Attachment icons */}
                                {selectedDocuments.length > 0 && (
                                    <div className={styles.attachmentPreviewContainer}>
                                        {selectedDocuments.map(({ title, type }, i) => (
                                            <div key={i} className={styles.attachmentChip}>
                                                {type.includes("pdf") ? (
                                                    <FaFilePdf className={styles.icon} />
                                                ) : type.includes("image") ? (
                                                    <FaFileImage className={styles.icon} />
                                                ) : (
                                                    <FaFileAlt className={styles.icon} />
                                                )}
                                                <span className={styles.label}>{title}</span>
                                                <button
                                                    className={styles.removeButton}
                                                    onClick={() => handleRemoveAttachment(i)}
                                                    aria-label={`Remove ${title}`}
                                                >
                                                    ❌
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </Form.Group>
                            <Row className="mt-3" controlId="attachmentInput">
                                <Form.Label><strong>Attachments</strong></Form.Label>
                                <Row>
                                    <Col md={8}>
                                        <Form.Control
                                            type="file"
                                            ref={fileInputRef}
                                            onChange={(e) => {
                                                const file = e.target.files[0];
                                                if (file) {
                                                    const newAttachment = {
                                                        title: file.name,
                                                        type: file.type || "application/octet-stream"
                                                    };
                                                    setSelectedDocuments((prev) => [...prev, newAttachment]);

                                                    // ✅ Reset the file input
                                                    e.target.value = null; // or fileInputRef.current.value = null;
                                                }
                                            }}
                                        />
                                    </Col>
                                    <Col md={4}>
                                        <Button variant="outline-secondary" onClick={() => setShowAttachments(true)}>
                                            <FaSearch style={{ marginRight: '6px' }} />
                                            Browse Repository
                                        </Button>
                                    </Col>
                                </Row>
                            </Row>

                            <Modal
                                show={showAttachments}
                                onHide={() => setShowAttachments(false)}
                                size="lg"
                                centered
                            >
                                <Modal.Header closeButton className={styles.modalHeader}>
                                    <Modal.Title>
                                        Documents for {selectedPatient?.name?.[0]?.given?.join(" ") + " " + selectedPatient?.name?.[0]?.family}
                                    </Modal.Title>
                                </Modal.Header>
                                <Modal.Body className={styles.modalBodyDark}>
                                    <AttachmentBrowser
                                        selectedPatient={selectedPatient}
                                        fhirClient={fhirClient}
                                        onAttach={(wrappedAttachments) => {
                                            setSelectedDocuments(wrappedAttachments); // ⬅️ store in state
                                            setShowAttachments(false); // ⬅️ close modal after selection
                                        }}
                                        onClose={() => setShowAttachments(false)} // fallback close button
                                    />
                                </Modal.Body>
                            </Modal>

                            {error && <p className="text-danger mt-2">{error}</p>}
                            <Button
                                type="submit"
                                variant="primary"
                                className="mt-3"
                                onClick={handleSubmit}
                            >
                                Send
                            </Button>
                        </Form>
                    </Card.Body>
                </Card>
            </Col>
            {/* Modal for Submission Status */}
            <Modal show={showStatusModal} onHide={() => setShowStatusModal(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Submission Status</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    {submissionResult}
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="success" onClick={() => setShowStatusModal(false)}>
                        OK
                    </Button>
                </Modal.Footer>
            </Modal>
        </Row>
    );
}

export default CommunicationForm;