import React, { useState, useEffect } from "react";
import {Accordion, Button, Container, Row, Col, ListGroup, Badge} from "react-bootstrap";
import AttachmentList from "./AttachmentList";
import { formatLocalDate } from "../utils/dateUtils";
import styles from "./AttachmentBrowser.module.css";
import { getIconForContentType } from "../utils/getIconForContentType";

const truncate = (str, maxLength = 25) =>
  str.length > maxLength ? str.slice(0, maxLength) + "…" : str;

const AttachmentBrowser = ({ selectedPatient, fhirClient, onAttach, onClose }) => {
  const patientId = selectedPatient?.id;
  const resourceTypes = ["DocumentReference", "DiagnosticReport", "Observation", "Media"];
  const [entries, setEntries] = useState([]);
  const [selectedEntry, setSelectedEntry] = useState(null);
  const [selectedAttachments, setSelectedAttachments] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchEntries = async () => {
    setLoading(true);
    const results = [];
    const fetchers = resourceTypes.map(async (type) => {
      try {
        const bundle = await fhirClient.request(`${type}?subject=Patient/${patientId}`, {
          pageLimit: 1,
          flat: false,
        });
        const typeEntries = Array.isArray(bundle.entry) ? bundle.entry : [];
        typeEntries.forEach(({ resource }) => {
          if (resource.id) {
            results.push({
              title: `Resource ID: ${resource.id}`,
              sourceType: resource.resourceType,
              resource,
            });
          }
        });
      } catch (err) {
        console.error(`Error fetching ${type}:`, err);
      }
    });

    await Promise.all(fetchers);
    setEntries(results);
    setLoading(false);
  };

  useEffect(() => {
    if (patientId && fhirClient) fetchEntries();
  }, [patientId, fhirClient]);

  const hasAttachments = (resource) =>
    (Array.isArray(resource.content) && resource.content.length > 0) ||
    (Array.isArray(resource.presentedForm) && resource.presentedForm.length > 0) ||
    (Array.isArray(resource.attachment) && resource.attachment.length > 0) ||
    (Array.isArray(resource.contained) &&
      resource.contained.some(
        (c) => Array.isArray(c.content) && c.content.some((i) => i.attachment?.url)
      ));

  const groupedEntries = resourceTypes.reduce((acc, type) => {
    acc[type] = entries.filter(
      (entry) => entry.sourceType === type && hasAttachments(entry.resource)
    );
    return acc;
  }, {});

  const getAttachmentCount = (type) => groupedEntries[type]?.length || 0;

  const toggleSelected = (wrapped) => {
    const { resourceId, index } = wrapped;
    console.log("Werapped selection:", wrapped);
    setSelectedAttachments((prev) => {
      const exists = prev.some((a) => a.resourceId === resourceId && a.index === index);
      return exists ? prev.filter((a) => !(a.resourceId === resourceId && a.index === index)) : [...prev, wrapped];
    });
  };

  const removeAttachment = (resourceId, index) => {
    setSelectedAttachments((prev) =>
      prev.filter((a) => !(a.resourceId === resourceId && a.index === index))
    );
  };

  const attachAndClose = () => {
    console.log("Wrapped Attachment Payload:", selectedAttachments);
    onAttach?.(selectedAttachments);
    onClose?.();
  };

  console.log("Selected attachments:", selectedAttachments);


  return (
    <Container fluid className="p-0">
      <Row className="mb-2">
        <Col>
          <Button
            variant="primary"
            onClick={attachAndClose}
            disabled={selectedAttachments.length === 0}
          >
            Attach ({selectedAttachments.length})
          </Button>
        </Col>
      </Row>

      {selectedAttachments.length > 0 && (
        <Row className="mb-3">
          <Col>
            <div className="d-flex flex-wrap">
              {selectedAttachments.map(({ fileType, resourceId, index, title, contentType, url }) => (
                <Badge
                  key={`${resourceId}-${index}`}
                  bg="info"
                  className="me-2 mb-1 d-flex align-items-center"
                  style={{ cursor: "pointer" }}
                  onClick={() => removeAttachment(resourceId, index)}
                >
                  {getIconForContentType(fileType, "Browser")}
                  <a
                    href={url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="ms-1 text-white text-decoration-underline"
                    onClick={(e) => e.stopPropagation()}
                  >
                    {truncate(title)}
                  </a>
                  <span className="ms-1 fw-bold">×</span>
                </Badge>
              ))}
            </div>
          </Col>
        </Row>
      )}

      <Row>
        <Col md={6}>
          <Accordion>
            {resourceTypes.map((type, idx) => (
              <Accordion.Item eventKey={idx.toString()} key={type}>
                <Accordion.Header>
                  {type} ({getAttachmentCount(type)})
                </Accordion.Header>
                <Accordion.Body>
                  {groupedEntries[type]?.length > 0 ? (
                    <ListGroup>
                      {groupedEntries[type].map((entry, i) => (
                        <ListGroup.Item
                          className={styles.entryItem}
                          key={i}
                          action
                          active={selectedEntry?.resource?.id === entry.resource?.id}
                          onClick={() => {
                            setSelectedEntry(entry);
                            console.log("Selected Entry:", entry);
                          }}
                        >
                          <strong>{entry.resource?.id}</strong> –{" "}
                          {entry.resource?.description || "No description"}
                          <br />
                          {formatLocalDate(entry.resource?.date) && (
                            <span>{formatLocalDate(entry.resource.date)}</span>
                          )}
                        </ListGroup.Item>
                      ))}
                    </ListGroup>
                  ) : (
                    <p>No entries found with attachments for {type}.</p>
                  )}
                </Accordion.Body>
              </Accordion.Item>
            ))}
          </Accordion>
        </Col>

        <Col md={6}>
          <div
            className="bg-light p-3 rounded"
            style={{ maxHeight: "60vh", overflowY: "auto" }}
          >
            <AttachmentList
              entry={selectedEntry}
              selectedAttachments={selectedAttachments}
              toggleSelected={toggleSelected}
              fhirClient={fhirClient}
            />
          </div>
        </Col>
      </Row>
    </Container>
  );
};

export default AttachmentBrowser;