import { useState } from "react";
import { FiSearch } from "react-icons/fi";

/**
 * @param {Function} setPayloadQuery - Callback to receive the user's raw query string
 */
const PayloadSearch = ({ setPayloadQuery }) => {
  const [query, setQuery] = useState("");

  const handleChange = (e) => {
    const newQuery = e.target.value;
    setQuery(newQuery);

    const safeQuery = typeof newQuery === "string" ? newQuery.trim() : "";

    if (typeof setPayloadQuery === "function") {
      setPayloadQuery(safeQuery); // 💬 update query live
    }
  };

  return (
    <div style={{ display: "flex", marginBottom: "0rem" }}>
      <input
        type="text"
        placeholder="search content..."
        value={query}
        onChange={handleChange}
        style={{
          flex: 1,
          padding: "8px",
          fontSize: "14px",
          borderRadius: "4px 0 0 4px",
          border: "1px solid #ccc",
          borderRight: "none"
        }}
      />
      <button
        onClick={() => {}}
        style={{
          padding: "8px",
          fontSize: "14px",
          borderRadius: "0 4px 4px 0",
          border: "1px solid #ccc",
          backgroundColor: "#f8f9fa",
          cursor: "default"
        }}
        aria-label="Search icon (decorative)"
      >
        <FiSearch />
      </button>
    </div>
  );
};

export default PayloadSearch;