import { createSlice } from "@reduxjs/toolkit";

const initialState = {
    byId: {},        // All messages indexed by ID
    threadMap: {},   // Map of anchorId -> array of message IDs
    pendingIds: []   // IDs of messages still awaiting confirmation/indexing
};

const messageSlice = createSlice({
    name: "messages",
    initialState,
    reducers: {
        addMessage: (state, action) => {
            const msg = action.payload;
            const msgId = msg.id;

            // Insert or update the message in byId
            state.byId[msgId] = {
                ...(state.byId[msgId] || {}),
                ...msg
            };

            // Find the anchor communication (start of thread)
            const anchorRef =
                msg.partOf?.[0]?.reference ||
                msg.inResponseTo?.[0]?.reference ||
                msg.id;
            const anchorId = anchorRef?.replace("Communication/", "") || msg.id;

            // Link message to thread
            if (!state.threadMap[anchorId]) {
                state.threadMap[anchorId] = [];
            }
            if (!state.threadMap[anchorId].includes(msgId)) {
                state.threadMap[anchorId].push(msgId);
            }

            // Track or untrack pending status
            const isPending = msg.meta?.isPending;
            const isAlreadyTracked = state.pendingIds.includes(msgId);

            if (isPending && !isAlreadyTracked) {
                state.pendingIds.push(msgId);
            } else if (!isPending && isAlreadyTracked) {
                state.pendingIds = state.pendingIds.filter(id => id !== msgId);
            }
        },

        markAsConfirmed: (state, action) => {
            const msgId = action.payload;
            const index = state.pendingIds.indexOf(msgId);
            if (index >= 0) {
                state.pendingIds.splice(index, 1);
            }
            if (state.byId[msgId]) {
                state.byId[msgId].meta = {
                    ...(state.byId[msgId].meta || {}),
                    isPending: false
                };
            }
        },

        setFullThread: (state, action) => {
            const { anchorId, messages } = action.payload;

            // Overwrite or insert new messages
            messages.forEach(msg => {
                state.byId[msg.id] = msg;
            });

            // Set thread ID list
            state.threadMap[anchorId] = messages.map(m => m.id);

            // Clean out any pending IDs that now appear confirmed
            const confirmedIds = new Set(messages.map(m => m.id));
            state.pendingIds = state.pendingIds.filter(id => !confirmedIds.has(id));
        },

        clearMessages: (state) => {
            state.byId = {};
            state.threadMap = {};
            state.pendingIds = [];
        }
    }
});

export const {
    addMessage,
    markAsConfirmed,
    setFullThread,
    clearMessages
} = messageSlice.actions;

export default messageSlice.reducer;