import { addMessage } from "../../slices/messageSlice"; // 🔁 Redux action to inject messages

/**
 * 🧹 Fetch and synchronize Communication messages from the FHIR server.
 * Promotes any previously pending local messages if they're confirmed in the server response.
 *
 * @param {string} anchorRef - FHIR reference like "Communication/abc123"
 * @param {object} fhirClient - An authorized FHIR client instance
 */
export const refreshCommunications = (anchorRef, fhirClient) => {
  console.log("🔄 Starting refreshCommunications for anchorRef:", anchorRef);

  return async (dispatch, getState) => {
    // 🧯 Defensive guards
    if (!anchorRef) {
      console.log("⚠️ No anchorRef provided to refreshCommunications");
      return;
    }
    if (!fhirClient) {
      console.log("⚠️ No fhirClient provided to refreshCommunications");
      return;
    }

    try {
      // 📡 Query server for all messages linked to the anchor thread
      const response = await fhirClient.request(`Communication?part-of=${anchorRef}`);
      const messages = (response.entry || []).map((e) => e.resource);

      //console.log(`📬 Fetched ${messages.length} messages from server`);

      const { byId } = getState().messages;

      messages.forEach((msg) => {
        const existingMeta = byId[msg.id]?.meta || {};
        const wasPending = existingMeta.isPending;

        if (wasPending) {
          console.log(`✅ Promoting message ${msg.id} from pending to confirmed`);
        } else if (!byId[msg.id]) {
          console.log(`🆕 New message detected: ${msg.id}`);
        }

        // 🚀 Inject or update message with refreshed meta
        dispatch(
          addMessage({
            ...msg,
            meta: {
              ...existingMeta,
              isPending: false // ✅ Mark as confirmed now
            }
          })
        );
      });
    } catch (err) {
      console.error("💥 refreshCommunications failed:", err);
    }
  };
};