async function resolveName(reference, store, fhirClient) {
  if (
    !reference ||
    typeof reference !== "string" ||
    reference === "Practitioner/undefined"
  ) {
    return null;
  }

  if (!reference.startsWith("Practitioner/")) {
    return null;
  }

  const practitionerId = reference.split("/")[1];
  const providers = store?.getState?.()?.providers;
  const cached = providers?.[practitionerId];

  if (cached?.name?.[0]) {
    const name = cached.name[0];
    const given = Array.isArray(name.given) ? name.given[0] : "";
    const family = name.family || "";
    const fullName = `${given} ${family}`.trim();
    return fullName || reference;
  }

  if (fhirClient) {
    try {
      const resource = await fhirClient.request(reference);
      const name = resource?.name?.[0];
      const given = Array.isArray(name?.given) ? name.given[0] : "";
      const family = name?.family || "";
      return `${given} ${family}`.trim() || reference;
    } catch (err) {
      console.warn("🔍 Failed to resolve name via FHIR:", reference, err);
      return reference;
    }
  }

  return reference;
}

module.exports = { resolveName };