import React, { useEffect, useState } from "react";
import { Card, Spinner, Alert, Modal, Button } from "react-bootstrap";
import { FaPaperclip } from "react-icons/fa";
import { useSelector, useDispatch } from "react-redux";
import styles from "./ThreadedMessageViewer.module.css";
import { store } from "./store/store"; // ✅ adjust this import path as needed

function ThreadedMessageViewer({ communication, fhirClient, contextProvider }) {
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [fetchError, setFetchError] = useState(null);
    const [threadTitle, setThreadTitle] = useState("Conversation");
    const byId = useSelector((state) => state.messages.byId);
    const dispatch = useDispatch();
    const threadMap = useSelector(state => state.messages.threadMap);
    const { resolveName } = require('./utils/resolveName');
    //const { fetchBinaryBlob } = require('./utils/fetchBinaryBlob');
    const { fetchAttachmentBlob } = require('./utils/fetchAttachmentBlob');
    
    const [showModal, setShowModal] = useState(false);
    const [modalMessage, setModalMessage] = useState("");

    useEffect(() => {
        //setLoading(true);
        let isMounted = true;
        const hydrateThreadLocally = async () => {
            try {
                const rawAnchor = communication.partOf?.[0]?.reference || `Communication/${communication.id}`;
                const anchorId = rawAnchor.split("/")[1]; // gets "2888342"

                const messageIds = threadMap?.[anchorId] || [];
                //console.log("🧵 Thread message IDs from threadMap:", messageIds);

                const selfId = contextProvider?.id?.split("/")?.pop();
                const participants = new Set();

                const rawMessages = messageIds
                    .map(id => byId?.[id])
                    .filter(Boolean);

                //console.log("📦 Resolved messages from Redux byId:", rawMessages.map(msg => msg.id));

                const enrichMessage = async (msg) => {
                    const senderRef = msg.sender?.reference;
                    const senderId = senderRef?.split("/")?.pop();
                    const isSelf = senderId === selfId;
                    const senderName = await resolveName(senderRef, store, fhirClient);
                    if (senderName) participants.add(senderName);

                    const recipientRefs = msg.recipient?.map(r => r.reference).filter(Boolean) || [];
                    for (const ref of recipientRefs) {
                        const name = await resolveName(ref, store, fhirClient);
                        if (name) participants.add(name);
                    }

                    const content = msg.payload?.find(p => p.contentString)?.contentString || "[No content]";
                    const attachments = msg.payload?.filter(p => p.contentAttachment)?.map(p => p.contentAttachment) || [];

                    const readReceipts = msg.extension?.filter(ext =>
                        ext.url === "http://yourdomain.org/fhir/StructureDefinition/read-receipt"
                    ) || [];

                    const readDetails = await Promise.all(
                        readReceipts
                            .filter(ext => {
                                const readerRef = ext.extension?.find(e => e.url === "user")?.valueReference?.reference;
                                const readerId = readerRef?.split("/")?.pop();
                                return readerId !== senderId;
                            })
                            .map(async (ext) => {
                                const userRef = ext.extension?.find(e => e.url === "user")?.valueReference?.reference;
                                const readerName = await resolveName(userRef, store, fhirClient);
                                const readAt = ext.extension?.find(e => e.url === "readAt")?.valueDateTime;
                                return readerName && readAt ? { reader: readerName, readAt } : null;
                            })
                    );

                    const status = isSelf
                        ? (msg.meta?.isPending ? "⏳ ...Sending" : "✅ Delivered")
                        : null;

                    return {
                        id: msg.id,
                        sent: msg.sent,
                        sender: senderName || senderRef || "Unknown",
                        isSelf,
                        content,
                        attachments,
                        status,
                        readDetails: readDetails.filter(Boolean)
                    };
                };

                const enrichedMessages = await Promise.all(rawMessages.map(enrichMessage));
                const sortedMessages = enrichedMessages.sort((a, b) => new Date(a.sent) - new Date(b.sent));

                if (isMounted) {
                    //console.log("💾 Updating viewer with enriched thread:", sortedMessages.map(m => m.id));
                    setMessages([...sortedMessages]);
                    setThreadTitle(Array.from(participants).join(", ") || "Unknown Participants");
                }
            } catch (err) {
                console.error("🚨 Failed to hydrate thread:", err);
                if (isMounted) setFetchError("Unable to load conversation.");
            } finally {
                if (isMounted) setLoading(false);
            }
        };

        if (communication && contextProvider && threadMap && byId) {
            hydrateThreadLocally();
            setLoading(true);
        } else {
            console.warn("⚠️ Missing required props or state — skipping thread hydration");
            setMessages([]);
            setLoading(false);
        }

        return () => {
            //console.log("🧹 Cleaning up viewer effect");
            isMounted = false;
        };
    }, [communication?.id, contextProvider, threadMap, byId]);




    if (fetchError) {
        return <Alert variant="danger">{fetchError}</Alert>;
    }

    return (
        <Card className="p-3 border border-dark bg-body-secondary">
            <Card.Header className={`d-flex justify-content-between align-items-center ${styles.conversationHeader}`}>
                <h5 className="mb-0">Participants: {threadTitle}</h5>
                {loading && (
                    <div className="d-flex align-items-center ms-2">
                        <Spinner animation="border" role="status" size="sm" variant="primary" />
                        <span className="ms-2 text-muted small">Loading...</span>
                    </div>
                )}
            </Card.Header>
            <div className="mt-3">
                {messages.map(msg => (
                    <Card
                        key={msg.id}
                        className={`mb-3 shadow-sm ${msg.isSelf ? styles.selfMessage : styles.receivedMessage} ${msg.id === communication?.id ? styles.selectedCard : ""}`}
                    >
                        <Card.Body>
                            <Card.Subtitle className="text-muted small mb-2 d-flex justify-content-between align-items-center">
                                <span>
                                    <strong>{msg.sender}</strong> · Sent:{" "}
                                    {new Date(msg.sent).toLocaleString()}
                                </span>
                                {msg.status && (
                                    <span
                                        style={{
                                            fontSize: "0.75rem",
                                            color: msg.status === "⏳ ...Sending" ? "#ff8800" : "#198754",
                                            fontWeight: "bold"
                                        }}
                                    >
                                        {msg.status}
                                    </span>
                                )}
                            </Card.Subtitle>
                            <Card.Text>{msg.content}</Card.Text>

                            {msg.readDetails?.length > 0 && (
                                <div className="mt-1 small text-muted">
                                    {msg.readDetails.map((entry, idx) => (
                                        <div key={idx}>
                                            👁️ Read by {entry.reader} {new Date(entry.readAt).toLocaleString()}
                                        </div>
                                    ))}
                                </div>
                            )}

                            {msg.attachments?.length > 0 && (
                                <div className="mt-2">
                                    <div className="fw-bold small">Attachments:</div>
                                    <ul className="list-unstyled mb-0">
                                        {msg.attachments.map((att, i) => (
                                            <li key={i}>
                                                <button
                                                    className="btn btn-link p-0"
                                                    onClick={async () => {
                                                        //const result = await fetchBinaryBlob(att.url, fhirClient);
                                                        const result = await fetchAttachmentBlob(att, fhirClient);
                                                        console.log(result);

                                                        if (result.deleted) {
                                                            setModalMessage(
                                                                `⚠️ This attachment is no longer available on the server.\n\n${result.reason || 'It was deleted from the server.'}`
                                                            );
                                                            setShowModal(true);
                                                            return;
                                                        }

                                                        if (!result.blob) {
                                                            setModalMessage(
                                                                `❌ Failed to fetch this attachment.\n\n${result.reason || 'An unknown error occurred.'}`
                                                            );
                                                            setShowModal(true);
                                                            return;
                                                        }

                                                        const blobUrl = URL.createObjectURL(result.blob);
                                                        const a = document.createElement("a");
                                                        a.href = blobUrl;
                                                        a.download = att.title || `Attachment-${i + 1}`;
                                                        a.click();
                                                    }}
                                                >
                                                    <FaPaperclip className="me-1" title="Attachment" />
                                                    {att.title || `Attachment ${i + 1}`} ({att.contentType})
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            )}
                        </Card.Body>
                    </Card>
                ))}
            </div>
            <Modal show={showModal} onHide={() => setShowModal(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Problem Fetching Attachment</Modal.Title>
                </Modal.Header>
                <Modal.Body style={{ whiteSpace: "pre-line" }}>{modalMessage}</Modal.Body>
                <Modal.Footer>
                    <Button variant="primary" onClick={() => setShowModal(false)}>
                        OK
                    </Button>
                </Modal.Footer>
            </Modal>
        </Card>


    );
}

export default ThreadedMessageViewer;